import csv
totals = {}
best = ("", -1)
with open("results.csv", newline="") as f:
    reader = csv.reader(f)
    next(reader)
    for name, team, points in reader:
        totals[team] = totals.get(team, 0) + int(points)
        if int(points) > best[1]:
            best = (name, int(points))
for team in sorted(totals):
    print(team, totals[team], sep=",")
print(best[0])
